UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>Become a civil engineer responsible for planning, designing and constructing projects that involve the built environment.<br/>From roads to railways, dams to harbors, houses to high-rises; civil engineers are responsible for the design and construction of all these assets. It is also civil engineers who work with other experts like builders, architects and clients to ensure that structures are safe, economical, and environmentally-sound. Students will learn how to prevent flooding, design irrigation systems and road infrastructure, and build multi-storeyed buildings. It is these skills that may see you specialize in structural engineering, geotechnical engineering, transport engineering, water engineering, or construction and infrastructure management.<br/>All online students are required to attend on campus block labs.</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Engineering</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 174000,
    onshore_tuition_fee = 38148,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic entry requirements</h5><p>Successful completion of Australian Year 12, or overseas equivalent.</p><h5>English language requirements</h5><p>Overall Academic IELTS band score of 6.0, with no band less than 6.0, or equivalent.</p><h5>Extra requirements</h5><ul> <li>Units 3 and 4: a study score of at least 20 in any English.</li> <li>Units 3 and 4: a study score of at least 20 in Maths: Mathematical Methods or</li> <li>Units 3 and 4: a study score of at least 20 in Maths: Specialist Mathematics or</li> <li>Units 3 and 4: a study score of at least 20 in Maths: General Mathematics.</li></ul><h5>ATAR</h5><p><p>Guaranteed ATAR Score 60</p></p><p>Applicable to onshore international students applying for undergraduate/bachelor degree programs only.</p><h4>Alternative Pathways</h4><p>Applicants who meet a score of at least 20 in any English but do not meet the requirement for Mathematics can alternatively complete EDMTH1000 Introduction to Technical Mathematics unit offered by the Federation University Australia Pathways program prior to admission into the degree.</p><p>Admission pathways for applicants without a year 12 qualification</p><ol> <li>Completion of a Diploma of Engineering (Higher Education) at Federation University Australia</li> <li>Completion of a cognate Certificate IV in engineering in addition to a pathway mathematics unit “Introduction to Technical Maths” by Federation University Australia’s Foundation Access Studies (FAST) course</li> <li>Completion of a cognate Diploma or Advanced Diploma in Engineering at a TAFE provider</li> <li>Completion of Federation University Australia’s Foundation Access Studies (FAST) course</li></ol>',
    apply_form = 'https://www.federation.edu.au/courses/den8.civ-bachelor-of-engineering-civil-honours',
    updated_at = NOW()
WHERE cricos_course_code = '116395A';
UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>Become a professional engineer who is an expert in planning, designing, and managing engineering projects. Invent new products, design innovative tools, and change how humans interact with machines. Learn about energy by studying thermodynamics and practice automation by exploring industrial robots. In your final year, pursue your interest area with your own unique engineering project. All online students are required to attend on campus block labs</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Engineering</p><h5>Course co-ordinator</h5><p>Truong Phung</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 174000,
    onshore_tuition_fee = 38148,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic entry requirements</h5><p>Successful completion of Australian Year 12, or overseas equivalent.</p><h5>English language requirements</h5><p>Overall Academic IELTS band score of 6.0, with no band less than 6.0, or equivalent</p><h5>Extra requirements</h5><ul> <li>Units 3 and 4: a study score of at least 20 in any English.</li> <li>Units 3 and 4: a study score of at least 20 in Maths: Mathematical Methods.</li> <li>Units 3 and 4: a study score of at least 20 in Maths: Specialist Mathematics.</li> <li>Units 3 and 4: a study score of at least 20 in Maths: General Mathematics.</li></ul><h5>ATAR</h5><p><p>Guaranteed ATAR Score 60</p></p><p>Applicable to onshore international students applying for undergraduate/bachelor degree programs only.</p><h4>Alternative Pathways</h4><p>Applicants who meet a score of at least 20 in any English but do not meet the requirement for Mathematics can alternatively complete EDMTH1000 Introduction to Technical Mathematics unit offered by the Federation University Australia Pathways program prior to admission into the degree.</p><p>Admission pathways for applicants without a year 12 qualification</p><ol> <li>Completion of a Diploma of Engineering (Higher Education) at Federation University Australia</li> <li>Completion of a cognate Certificate IV in engineering in addition to a pathway mathematics unit “Introduction to Technical Maths” by Federation University Australia’s Foundation Access Studies (FAST) course</li> <li>Completion of a cognate Diploma or Advanced Diploma in Engineering at a TAFE provider</li> <li>Completion of Federation University Australia’s Foundation Access Studies (FAST) course</li></ol>',
    apply_form = 'https://www.federation.edu.au/courses/den8.mec-bachelor-of-engineering-mechanical-honours',
    updated_at = NOW()
WHERE cricos_course_code = '116397K';
UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>The Bachelor of Engineering (Mining) (Honours) will equip you with the necessary communication, technical and problem solving skills required to meet the high demand for graduates in mining engineering in Australia and the Asia Pacific Region.</p><p>Throughout the course you will explore study areas in mineral deposit evaluation and processing underground production systems mine power and services surface mining operations and mine environment and safety to establish best practice in sustainable and safe mining.</p><p>The Bachelor of Engineering (Mining) (Honours) is a four-year course accredited by Engineers Australia the global home for engineering professionals renowned as leaders in shaping a sustainable world. As an accredited mining engineer you can work in government and private organisations mining companies and consulting firms to design install and supervise the use of mining machinery and equipment inspect the progress of mining operations and work with geologists to investigate and carry out the extraction of ore bodies and mineral deposits. If you wish to progress to further study you may consider a Master of Engineering course.</p><p>The Federation University Co-operative Model will accelerate your career by putting you at the heart of education and industry. Federation Co-op creates a direct connection between students and employers, via paid placements, career preparation and workplace skill development, supported by a leader in student support, skills development and social equity. Our industry stakeholders are excited about Federation Co-op as it addresses skill shortages by inviting them to collaborate on our courses, to identify the real skills that our students need to succeed in their chosen industry.</p><p>Co-op means you can succeed wherever you start on your study journey.</p><p>Federation has the know-how to deliver Co-op through our award-winning relationships with industry, including our 25+ year partnership with IBM, and our extensive research into the co-op model’s success in the USA, Canada and Europe for generations of students.</p><ul> <li>Work and world ready graduates. We prepare our students through mandatory career development units, so you will be ready to enter the workforce during your co-operative placements, and through transferable World Ready Skills, so you are workforce ready when you graduate, regardless of your background before going to uni.</li> <li>Real experience in your chosen profession. Every Co-op student completes a minimum of 60 days’ paid placement relevant to their course – contributing directly to course credits – either full time over one semester, part time over an extended period or in blocks embedded into your subjects.</li></ul><p>Co-op offers flexibility to suit our students’ commitments and course. Co-design, co-develop and co-delivered with industry. We work with employers, industry, students and alumni to co-design, co-develop and co-deliver a comprehensive set of structured, assessed Co-operative Experiential Learning activities.</p><p>Please note: All online-enrolled students are required to attend a limited number of on-campus intensive labs as part of their course.</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Engineering</p><h5>Course co-ordinator</h5><p>Mt Helen (on campus) - Manoj Khandelwal<br/>Online - Manoj Khandelwal</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 174000,
    onshore_tuition_fee = 38148,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic entry requirements</h5><p>Successful completion of Australian Year 12, or overseas equivalent.</p><h5>English language requirements</h5><p>Overall Academic IELTS band score of 6.0, with no band less than 6.0, or equivalent.</p><h5>Extra requirements</h5><ul> <li>Units 3 and 4: a study score of at least 20 in any English and</li> <li>Units 3 and 4: a study score of at least 20 in Maths: Mathematical Methods or</li> <li>Units 3 and 4: a study score of at least 20 in Maths: Specialist Mathematics or</li> <li>Units 3 and 4: a study score of at least 20 in Maths: General Mathematics.</li></ul><h5>ATAR</h5><p><p>Guaranteed ATAR Score 60</p></p><p>Applicable to onshore international students applying for undergraduate/bachelor degree programs only.</p><h4>Alternative Pathways</h4><p>Applicants who meet a score of at least 20 in any English but do not meet the requirement for Mathematics can alternatively complete EDMTH1000 Introduction to Technical Mathematics unit offered by the Federation University Australia Pathways program prior to admission into the degree.</p><p>Admission pathways for applicants without a year 12 qualification</p><ol> <li>Completion of a Diploma of Engineering (Higher Education) at Federation University Australia</li> <li>Completion of a cognate Certificate IV in engineering in addition to a pathway mathematics unit “Introduction to Technical Maths” by Federation University Australia’s Foundation Access Studies (FAST) course</li> <li>Completion of a cognate Diploma or Advanced Diploma in Engineering at a TAFE provider</li> <li>Completion of Federation University Australia’s Foundation Access Studies (FAST) course</li></ol>',
    apply_form = 'https://www.federation.edu.au/courses/den8.min-bachelor-of-engineering-mining-honours',
    updated_at = NOW()
WHERE cricos_course_code = '116399H';
UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>Be part of a rapidly evolving industry with extraordinary opportunities. Artificial Intelligence systems are playing a key role in the modern world, meaning professionals with high level IT and Data Science qualifications are in high demand.</p><p>The Bachelor of Information Technology (Artificial Intelligence and Data Science) gives you a broad knowledge applicable to the IT industry in both well-established technologies and emerging IT trends. In your first year of study you’ll obtain the required core IT foundations, and then become ‘job-ready’ by completing specialist AI and Data Science units, plus our mandatory career development units including 60 days of paid placement through Federation Co-op.</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Information Technology</p><h5>Course co-ordinator</h5><p>Bhavna Antony</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 124200,
    onshore_tuition_fee = 28611,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic entry requirements</h5><p>Successful completion of Australian Year 12, or overseas equivalent.</p><h5>English language requirements</h5><p>Overall Academic IELTS band score of 6.0, with no band less than 6.0, or equivalent</p><h5>ATAR</h5><p><p>Guaranteed ATAR Score 50</p></p><p>Applicable to onshore international students applying for undergraduate/bachelor degree programs only.</p>',
    apply_form = 'https://www.federation.edu.au/courses/dit5.ads-bachelor-of-information-technology-ai-and-data-science',
