    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic entry requirements</h5><p>Successful completion of Australian Year 12,or overseas equivalent.<br/> </p><h5>English language requirements</h5><p>IELTS score of 7.0 or greater will be required with no band less than 7, or equivalent.</p><h5>ATAR</h5><p><p>Guaranteed ATAR 90.00</p><p>Lowest Adjusted ATAR 75.00</p></p><p>Applicable to onshore international students applying for undergraduate/bachelor degree programs only.</p>',
