UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>The Doctor of Philosophy (PhD) is an elite higher degree qualification completed solely by research. Graduates at this level will have systemic and critical understanding of a substantial and complex body of knowledge at the frontier of a discipline or area of professional practice.<br/>Undertaken over four years of full-time study, the PhD enables a candidate to create authoritative capabilities for independent research, demonstrated through the completion of a substantial thesis, or creative works with exegesis. Throughout their research journey, the candidate works closely with a supervisory team who provide academic guidance and support. <br/>Candidates in this course would undertake a research project within the broad areas of agriculture or environmental sciences.</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Graduate Research School</p><h5>Course co-ordinator</h5><p>Andrew Barton</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 108000,
    onshore_tuition_fee = 33500,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><p>To be eligible for admission as a candidate for the degree of Doctor of Philosophy an applicant must:</p><ul> <li>have graduated with or qualified for a Masters degree that included a dissertation demonstrating the ability to undertake research at PhD level; or</li> <li>have graduated with or qualified for a four year Honours Bachelor degree, or Degree with Honours at first class or second class, upper division, honours, that included a dissertation demonstrating the ability to undertake research at PhD level; or</li> <li>have been enrolled for a Masters degree by research and have completed research which is assessed by the academic Board as demonstrating the capacity to undertake research at PhD level; or</li> <li>hold qualifications and/or have demonstrated skills, experience, research, or publications which are assessed by the Academic Board as being at least equivalent to or as a satisfactory substitute for any of the qualifications prescribed above.</li></ul><h5>English language requirements</h5><p>Overall academic IELTS of 6.5 overall with no band less than 6.0; or equivalent</p>',
    apply_form = 'https://www.federation.edu.au/courses/del0-doctor-of-philosophy/',
    updated_at = NOW()
WHERE cricos_course_code = '119362H';
