UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>This course provides an opportunity for you to develop an advanced understanding of data science by incorporating and interpreting complex information, concepts and theories to relevant disciplines, using data science tools and methods to manage, process, and analyse data.</p><p>Throughout the course, you will utilise your skills to handle large volumes of data, working with real-time data, cloud computing, unstructured data and statistical models.</p><p>As a graduate, you may work in data science related areas such as the health care, finance, government administration and IT industries.</p><p>To review entry requirements and application details relevant to you, please indicate whether you are a domestic or international student by selecting the filter in the top right corner of the screen.</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Engineering</p><h5>Course co-ordinator</h5><p>Savin Chand</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 82800,
    onshore_tuition_fee = 19074,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic entry requirements</h5><p>Applicants will have completed an undergraduate degree at AQF level 7 in an area of science, mathematics, statistics, engineering, information technology or business.<br/>Students will be required to demonstrate they have previously studied introductory mathematics and at least one information technology course in their undergraduate degree. If they cannot, they must select an approved elective course in their first semester of study to meet prerequisite requirements.</p><h5>English language requirements</h5><p>Overall IELTS band score of 6.0, with no band less than 6.0 or equivalent.</p><h4>Alternative Pathways</h4><p>This is an applied postgraduate course and does not directly lead to further coursework study.</p><p>However, by virtue of the 60 credit point project and research methods course, students may complete a research thesis and use this as a pathway to a higher degree by research.</p>',
    apply_form = 'https://www.federation.edu.au/courses/dcx9-master-of-data-science/',
    updated_at = NOW()
WHERE cricos_course_code = '118376K';
UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>The Master of Philosophy (MPhil) is a higher degree by research qualification completed solely by research. Graduates at this level will have an advanced and integrated understanding of a complex body of knowledge. <br/>Undertaken over two years of full-time study, the MPhil requires candidates to demonstrate their capacity for independent research through the submission of a substantial thesis, or a portfolio of creative works accompanied by an exegesis. Throughout their research journey, the candidate works closely with a supervisory team who provide academic guidance and support. <br/>Candidates in this course would undertake a research project within the broad area of education.</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Graduate Research School</p><h5>Course co-ordinator</h5><p>Andrew Barton</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 59000,
    onshore_tuition_fee = 26900,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><p>Successful completion of an Honours degree at class 2B level, or its overseas equivalent.</p><h5>English language requirements</h5><p>Overall academic IELTS of 6.5 overall with no band less than 6.0; or equivalent</p>',
    apply_form = 'https://www.federation.edu.au/courses/ded9-master-of-philosophy/',
    updated_at = NOW()
WHERE cricos_course_code = '119352K';
UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>Graduates of this course will have the specialist knowledge required to understand and implement advanced software engineering techniques - design, implement and maintain IT systems using a well-informed software engineering approach and create high quality software in a systematic and efficient manner. Graduates may find employment in a wide range of industries including security and defence, education, aerospace, health, business and finance.</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Information Technology</p><h5>Course co-ordinator</h5><p>Azadeh Noori Hoshyar</p>',
