UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>The Bachelor of Business (Marketing and Management) will prepare you for professional work in a contemporary business environment. Your studies will include core subjects in market research and consumer behaviour, business strategy, social media, communications and more. This course provides you with real experience in your chosen profession, through our Co-operative Model. Please see the Placement section for more details.</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Business</p><h5>Course co-ordinator</h5><p>Christine Peacock</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 118800,
    onshore_tuition_fee = 52197,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic entry requirements</h5><p>Successful completion of Australian Year 12, or overseas equivalent.</p><h5>English language requirements</h5><p>Overall Academic IELTS band score of 6.0, with no band less than 6.0, or equivalent.</p><h4>Alternative Pathways</h4><p>GB1 Diploma of Business</p>',
