UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>As a professional mining engineer you will oversee teams of engineering technologists and skilled trade staff to construct the designs you have created and work at a theoretical level to isolate analyse and define engineering outcomes. Mining engineers are in high demand in Australia and the Asia Pacific Region and work in all parts of the industry including feasibility studies mine design and managing production and sales. As a graduate you will be eligible to become a member of Engineers Australia and seek managerial roles with private consultants contracting companies or federal state and local government organisations. Upon successful completion you will be eligible for entry into the Graduate Diploma of Mining; Master of Engineering Technology (Mining) or the Master of Health (Workplace Health and Safety).<br/>This course provides you with real experience in your chosen profession, through our Co-operative Model. Please see the Work integrated learning section below for more details.</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Engineering</p><h5>Course co-ordinator</h5><p>Manoj Khandelwal</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 87000,
    onshore_tuition_fee = 19074,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic entry requirements</h5><p>Successful completion of an Australian bachelor’s degree or overseas equivalent.</p><p>Successful completion of a recognised 3- or 4-year Engineering Bachelor Degree in the relevant specialisation (major field) with credit average, awarded by an Australian University, or a recognised overseas equivalent.</p><h5>English language requirements</h5><p>Overall Academic IELTS band score of 6.0, with no band less than 6.0, or equivalent</p>',
    apply_form = 'https://www.federation.edu.au/courses/dez9.min-master-of-engineering-technology-mining',
