UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>This course provides you with a wide variety of major and minor study areas to choose from based on your interests and career aspirations.</p><p>Apply for our Bachelor of Science and study a generalised first year, with the flexibility to choose from a wide range of major and minor study areas :</p><ul> <li>Biochemistry</li> <li>Cell Biology Major</li> <li>Chemistry</li> <li>Ecology</li> <li>Environmental Restoration</li> <li>Laboratory Bioscience</li> <li>Microbiology</li></ul><p>Accelerate your career with Co-op. This course also provides you with real experience in your chosen profession through our Co-operative Model. Please see the Placement section for more details.</p><p>All online students will be required to attend on campus block labs and field trips.</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Science</p><h5>Course co-ordinator</h5><p>Berwick (on campus) - Alison Green<br/>Gippsland (on campus) - David Smith<br/>Mt Helen (on campus) - Alison Green<br/>Online - David Smith</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 116700,
    onshore_tuition_fee = 28611,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic entry requirements</h5><p>Successful completion of Australian Year 12 with one final year course in Mathematics (any) or one final year<br/>course of either Chemistry, Biology or Physics or overseas equivalent.</p><h5>English language requirements</h5><p>Overall Academic IELTS band score of 6.0, with no band less than 6.0, or equivalent</p><h5>ATAR</h5><p><p>Guaranteed ATAR Score 60</p></p><p>Applicable to onshore international students applying for undergraduate/bachelor degree programs only.</p>',
    apply_form = 'https://www.federation.edu.au/courses/dsi5-bachelor-of-science/',
