UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>The Graduate Diploma in Mining was created with the working engineer in mind. Intended as continuing education for scientists and engineers already involved with the mining industry, it is expected to appeal particularly to civil, mechanical, electrical, chemical and construction engineers, geologists, metallurgists, surveyors and other professionals with an interest in mining practice. This course will build upon the knowledge already gained from invaluable industry experience.</p><p>With a range of study modes available, from part time online learning to full time on campus study, this course can be tailored to suit your needs.</p><p>The course is designed for full-time study over two years or part-time study over a four year period either via online learning*or via block mode in the form of several full-time periods on campus of one week each, followed by assignments and practical work in the student''s place of employment.</p><p>Persons not wishing, or not able to, finish the course in minimum time may attend full or half sessions once or twice per year until the required number of courses have been completed.</p><p><em>*Domestic students only, international students are required to study full-time at the Mt Helen Campus.</em></p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Engineering</p><h5>Course co-ordinator</h5><p>Manoj Khandelwal</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 84000,
    onshore_tuition_fee = 19074,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic entry requirements</h5><p>Successful completion of a recognised 3-year Australian bachelor degree or overseas equivalent.</p><h5>English language requirements</h5><p>Overall IELTS score of 6.0, with no band less than 6.0, or equivalent.</p><h5>Extra requirements</h5><p>There are no additional entry requirements to enter this course other than the University Entry Requirements listed above.</p><h4>Alternative Pathways</h4><p>International students: A three or four years bachelor''s degree in Engineering, Science, IT or Business.<br/>Domestic students: (we generally look at a case-by-case basis)<br/>A three or four years bachelor''s degree in Engineering, Science, IT or Business.<br/>Or Relevant industry experience of +2 years</p>',
    apply_form = 'https://www.federation.edu.au/courses/deq4-graduate-diploma-of-mining/',
    updated_at = NOW()
WHERE cricos_course_code = '085622M';
UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>This course will provide you with the opportunity to gain a deeper understanding of relevant topics and technology pertaining to threats detection, risk analytics, data security, incident response, privacy protection, security audit and compliance, using innovative technologies from leading vendors like Amazon Web Services (AWS) and IBM.<br/> <br/>Core and elective subjects will allow you to develop the knowledge and skills to analyse, inspect and prevent cyber risks by adopting new practices and policies, in various sectors including e-commerce, banking, digital health, education, food and agriculture. Capstone projects in privacy, security, trust, analytics and/or data management, incorporate elements of management and leadership to further develop your understanding of technical and business principles.</p><p>Subjects within this course are associated with the AWS cloud online virtual software platform, preparing you for AWS Certification.</p><p>The course aligns with <a href="http://www.csmining.org">International Cybersecurity Data Mining Competition</a> and aligns with current industry trends through an advisory board of Australian industry leaders.</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Information Technology</p><h5>Course co-ordinator</h5><p>Shaoning Pang</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 82800,
    onshore_tuition_fee = 19074,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic entry requirements</h5><p>Successful completion of a recognised 3-year Australian bachelor degree or overseas equivalent.</p><h5>English language requirements</h5><p>Overall IELTS band score of 6.0, with no band less than 6.0, or equivalent.</p><h4>Alternative Pathways</h4><p>Graduates, who have completed high quality research projects, will have the opportunity to expand their knowledge and skills by enrolling in a PhD course.</p>',
    apply_form = 'https://www.federation.edu.au/courses/dcq9-master-of-applied-cyber-security/',
