    entry_requirements = '<h4>Entry Requirements</h4><p>To be eligible for admission as a candidate for the degree of Doctor of Philosophy an applicant must:</p><ul> <li> possess a degree that is the equivalent to an AQF Bachelor degree with Honours with first class or second class, first division, for entry to a PhD or at least third class honours for entry to a Masters by Research, or</li> <li> possess a Masters degree with a relevant research component that is equivalent to a Masters degree from Federation University and an equivalent result as outlined above, or</li> <li> submit other evidence of relevant qualifications and experience, or research experience, to confirm that the applicant possesses a level of relevant research experience and capacity equivalent to an award in either point above, and</li> <li> satisfy such additional requirements for admission to a PhD candidature, if any, as may be prescribed by the Graduate Research School Board</li></ul><h5>English language requirements</h5><p>Academic IELTS of 6.5 overall with no band less than 6.0; or equivalent</p><h4>Alternative Pathways</h4><p>There is provision for transfer from Masters by Research to PhD candidature with credit for the period spent as a Masters by Research candidate.</p>',
    apply_form = 'https://www.federation.edu.au/courses/din0-doctor-of-philosophy/',
    updated_at = NOW()
WHERE cricos_course_code = '119307D';
