UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>Through this degree you will gain the skills needed to analyse the principles of cyber threat detection, analytics, incident response, and security operation planning. </p><p>You will also learn how to critically evaluate and analyse evolving cyber security trends, while applying your knowledge of cyber security practices to assess risks and implement effective countermeasures.</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Information Technology</p><h5>Course co-ordinator</h5><p>Shaoning Pang</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 82800,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic entry requirements</h5><p>Successful completion of a bachelor’s degree in an IT-related discipline, or in a non-IT discipline with either a significant IT component or with relevant IT industry experience. The applicant''s entire academic record and industry experience can be taken into consideration when assessing eligibility for the course.</p><h5>English language requirements</h5><p>Overall Academic IELTS band score of 6.0, with no band less than 6.0, or equivalent.</p><h5>Extra requirements</h5><p><br/> </p>',
    apply_form = 'https://www.federation.edu.au/courses/dfq9-master-of-forensic-cyber-security/',
