UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>The Master of Philosophy (MPhil) is a higher degree by research qualification completed solely by research. Graduates at this level will have an advanced and integrated understanding of a complex body of knowledge. <br/>Undertaken over two years of full-time study, the MPhil requires candidates to demonstrate their capacity for independent research through the submission of a substantial thesis, or a portfolio of creative works accompanied by an exegesis. Throughout their research journey, the candidate works closely with a supervisory team who provide academic guidance and support. <br/>Candidates in this course would undertake a research project within the broad area of engineering.</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Graduate Research School</p><h5>Course co-ordinator</h5><p>Andrew Barton</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 72000,
    onshore_tuition_fee = 33500,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><p>Successful completion of an Honours degree at class 2B level, or its overseas equivalent.</p><h5>English language requirements</h5><p>Overall academic IELTS of 6.5 overall with no band less than 6.0; or equivalent</p>',
    apply_form = 'https://www.federation.edu.au/courses/def9-master-of-philosophy/',
