UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>Let our experienced lecturers help invigorate your career with new skills and knowledge. If you don’t already have a formal accounting qualification and you’re ready to break into this thriving field, our Master of Professional Accounting is the perfect place to start. It is a particularly attractive choice for those seeking practical accreditation on top of their existing tertiary education.</p><p>Accounting, finance and economics are about more than just looking at numbers. Our Master of Professional Accounting will provide you with a fresh perspective in using this information to provide expert advice and positively impact the lives of people around the world.</p><p>You will develop a comprehensive knowledge in key areas such as financial reporting, taxation, auditing, and budgeting. You’ll also learn the legal ins and outs of associated compliance and performance requirements to ensure statutory and strategic governance.</p><p>Our course will provide you with a comprehensive course of study in accounting theory and practice that is recognised by the Certified Practising Accountants (CPA) and Chartered Accountants of Australia and New Zealand (CAANZ), enabling you to pursue a pathway to qualification as a professional accountant.</p><p>As the next generation of professional accountants, you’ll be at the forefront of a changing business environment focusing less about profits, and more on caring for the world we live in: from quantifying the financial benefits of sustainable, fair trade business practices; to providing evidence-based solutions to emerging issues and business challenges.</p><p>Please note that online delivery is not available to international students on student visas.</p><p>This course also offers two exit points, the <a href="http://study.federation.edu.au/#/course/DBI4">Graduate Certificate of Professional Accounting</a> (8 units) and the <a href="http://study.federation.edu.au/#/course/DBO4">Graduate Diploma of Professional Accounting</a> (12 units).</p><h4>Additional information</h4><h5>IT requirements</h5><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h5>Got questions?</h5><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h5>Student support</h5><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h5>The fine print</h5><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h5>School department</h5><p>Business</p><h5>Course co-ordinator</h5><p>Abdel Halabi</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 79200,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h5>Academic entry requirements</h5><p>Completion of an undergraduate degree in a non-accounting discipline or equivalent<br/><br/>This course is intended for applicants with an undergraduate degree in a non-accounting discipline who are looking for a career in professional accounting. It can also meet the needs of people who have significant experience working in accounting and who now wish to increase their knowledge, skills, and recognition and employment options by having a high-level qualification in this area. In exceptional circumstances, applicants who do not have a bachelor''s degree may be admitted on the basis of relevant work experience, and demonstrated capacity to undertake the course as determined by Federation Business School, following an evaluationof their academic and professional skills.</p><h5>English language requirements</h5><p>Overall IELTS band score of 6.0, with no individual sub-scorebelow 6.0 (or equivalent)</p><h5>Extra requirements</h5><p>There are no additional entry requirements to enter this course other than the University Entry Requirements listed above</p>',
    apply_form = 'https://www.federation.edu.au/courses/dbx9-master-of-professional-accounting/',
    updated_at = NOW()
WHERE cricos_course_code = '119408K';
